// ---------------------------------------------------------------------------
// frame_arb_mux_tb -- self-checking testbench for frame_arb_mux
// Checks S3 (frame atomicity), S4 (payload integrity/order/tlast),
// S5 (no loss/duplication), S8 (backpressure), S10 (bounded fairness),
// S12 (reset behaviour).  S9/S11/out-of-scope items are deliberately not
// checked.
// ---------------------------------------------------------------------------
module frame_arb_mux_tb;

  localparam int S_COUNT    = 4;
  localparam int DATA_WIDTH = 32;
  localparam int USER_WIDTH = 1;
  localparam int KEEPW      = DATA_WIDTH/8;

  // ---- clock ---------------------------------------------------------------
  logic clk;
  initial begin clk = 1'b0; forever #5 clk = ~clk; end

  // ---- reset ---------------------------------------------------------------
  logic rst;
  initial rst = 1'b1;

  // ---- DUT signals (packed forms match the port map exactly) ---------------
  logic [S_COUNT-1:0][DATA_WIDTH-1:0]  s_tdata;
  logic [S_COUNT-1:0][KEEPW-1:0]        s_tkeep;
  logic [S_COUNT-1:0]                   s_tvalid;
  logic [S_COUNT-1:0]                   s_tlast;
  logic [S_COUNT-1:0][USER_WIDTH-1:0]   s_tuser;
  logic [S_COUNT-1:0]                   s_tready;

  logic [DATA_WIDTH-1:0]                m_tdata;
  logic [KEEPW-1:0]                     m_tkeep;
  logic                                 m_tvalid;
  logic                                 m_tready;
  logic                                 m_tlast;
  logic [USER_WIDTH-1:0]                m_tuser;

  frame_arb_mux #(
    .S_COUNT(S_COUNT), .DATA_WIDTH(DATA_WIDTH), .USER_WIDTH(USER_WIDTH)
  ) dut (
    .clk_i(clk), .rst_i(rst),
    .s_tdata_i(s_tdata), .s_tkeep_i(s_tkeep), .s_tvalid_i(s_tvalid),
    .s_tready_o(s_tready), .s_tlast_i(s_tlast), .s_tuser_i(s_tuser),
    .m_tdata_o(m_tdata), .m_tkeep_o(m_tkeep), .m_tvalid_o(m_tvalid),
    .m_tready_i(m_tready), .m_tlast_o(m_tlast), .m_tuser_o(m_tuser)
  );

  // ---- expected-beat model --------------------------------------------------
  typedef struct packed {
    logic [DATA_WIDTH-1:0] data;
    logic [KEEPW-1:0]      keep;
    logic [USER_WIDTH-1:0] user;
    logic                  last;
  } beat_t;

  // one queue per input (case-selected wrappers keep Verilator happy)
  beat_t q0[$], q1[$], q2[$], q3[$];

  function automatic int qsize(input int k);
    case (k)
      0: return q0.size();
      1: return q1.size();
      2: return q2.size();
      default: return q3.size();
    endcase
  endfunction

  task automatic qpush(input int k, input beat_t b);
    case (k)
      0: q0.push_back(b);
      1: q1.push_back(b);
      2: q2.push_back(b);
      3: q3.push_back(b);
    endcase
  endtask

  function automatic beat_t qfront(input int k);
    case (k)
      0: return q0[0];
      1: return q1[0];
      2: return q2[0];
      default: return q3[0];
    endcase
  endfunction

  task automatic qpop(input int k);
    case (k)
      0: void'(q0.pop_front());
      1: void'(q1.pop_front());
      2: void'(q2.pop_front());
      3: void'(q3.pop_front());
    endcase
  endtask

  task automatic qclr(input int k);
    case (k)
      0: q0.delete();
      1: q1.delete();
      2: q2.delete();
      3: q3.delete();
    endcase
  endtask

  // ---- bookkeeping ----------------------------------------------------------
  int  errors      = 0;
  int  in_flight   = 0;   // beats accepted on inputs, not yet seen on output
  int  cur_in      = -1;  // input whose frame is currently on the output
  int  gen         = 0;   // generation tag, toggled on reset (S12)
  bit  bad_frame   = 1'b0;
  bit  fair_chk    = 1'b0;
  bit  done_k      [S_COUNT];
  int  frames_done = 0;
  int  last_start  [S_COUNT];
  int  fcnt        [S_COUNT];

  task automatic fail(input string req, input string msg);
    errors++;
    $display("FAIL %s: %s (time %0t)", req, msg, $time);
  endtask

  // S10: under continuous offered load every input must begin a frame within
  // any window of 16 consecutive completed output frames.
  task automatic chk_fair();
    if (fair_chk) begin
      for (int j = 0; j < S_COUNT; j++) begin
        if (!done_k[j] && (frames_done - last_start[j] > 16)) begin
          fail("S10", $sformatf("input %0d began no frame within %0d completed output frames",
                                j, frames_done - last_start[j]));
          fair_chk = 1'b0; // report once, avoid spam
        end
      end
    end
  endtask

  // ---- BFM -------------------------------------------------------------------
  task automatic bfm_reset(input int cycles = 4);
    @(negedge clk);
    rst = 1'b1;
    repeat (cycles) @(posedge clk);
    @(negedge clk);
    rst = 1'b0;
  endtask

  // Offers ONE beat on input k, returns once it transferred (S7 compliant).
  // The beat is entered into the expected model at presentation time (negedge)
  // so that a zero-latency implementation that forwards it on the very next
  // posedge is still checked correctly.
  task automatic bfm_send(input int k, input logic [DATA_WIDTH-1:0] data,
                          input logic [KEEPW-1:0] keep, input logic last,
                          input logic [USER_WIDTH-1:0] user);
    beat_t b;
    @(negedge clk);
    s_tdata[k]  = data;
    s_tkeep[k]  = keep;
    s_tlast[k]  = last;
    s_tuser[k]  = user;
    s_tvalid[k] = 1'b1;
    b.data = data;
    b.keep = keep;
    b.user = user;
    b.last = last;
    qpush(k, b);
    in_flight++;
    forever begin
      @(posedge clk);
      if (s_tready[k]) break;
    end
  endtask

  task automatic bfm_idle(input int k);
    @(negedge clk);
    s_tvalid[k] = 1'b0;
  endtask

  task automatic bfm_ready(input logic value);
    @(negedge clk);
    m_tready = value;
  endtask

  // ---- stimulus helpers -------------------------------------------------------
  // data[31:28]=input, [27]=generation, [26:16]=frame id, [15:0]=beat id
  function automatic logic [DATA_WIDTH-1:0] mk_data(input int k, input int fid, input int bid);
    logic [DATA_WIDTH-1:0] d;
    d = '0;
    d[31:28] = k;
    d[27]    = gen[0];
    d[26:16] = fid;
    d[15:0]  = bid;
    return d;
  endfunction

  task automatic send_frame(input int k, input int nbeats);
    for (int i = 0; i < nbeats; i++) begin
      bfm_send(k, mk_data(k, fcnt[k], i), $urandom, (i == nbeats-1), $urandom);
    end
    fcnt[k]++;
  endtask

  task automatic drain_frames(input string tag);
    int guard;
    guard = 0;
    while (in_flight != 0 && guard < 20000) begin
      @(posedge clk);
      guard++;
    end
    if (in_flight != 0)
      fail("S5", $sformatf("%s: %0d accepted input beats never appeared on the output",
                           tag, in_flight));
  endtask

  // ---- output checker ----------------------------------------------------------
  // Runs on the sampling edge; everything it reads was driven on the opposite
  // edge (or by the DUT itself), so there is no same-timestep race.
  always @(posedge clk) begin
    if (!rst && m_tvalid && m_tready) begin
      automatic int    k;
      automatic beat_t b;
      automatic bit    ok;
      if (bad_frame) begin
        // a mismatch was already reported; ride out the rest of this frame
        if (m_tlast) begin
          bad_frame = 1'b0;
          cur_in = -1;
          frames_done++;
          chk_fair();
        end
      end else if (cur_in == -1) begin
        // first beat of a new output frame: identify the source input
        k  = m_tdata[31:28];
        ok = 1'b0;
        if (k >= S_COUNT) begin
          fail("S4", "output beat does not decode to a valid input number");
          bad_frame = 1'b1;
        end else if (m_tdata[27] != gen[0]) begin
          fail("S12", "beat that transferred before/during reset appeared on the output afterwards");
          bad_frame = 1'b1;
        end else if (qsize(k) == 0) begin
          fail("S4", "output beat matches no outstanding accepted input beat");
          bad_frame = 1'b1;
        end else begin
          b = qfront(k);
          if (b.data === m_tdata && b.keep === m_tkeep &&
              b.user === m_tuser && b.last === m_tlast) begin
            ok = 1'b1;
          end else begin
            fail("S4", "first beat of frame: payload/tkeep/tuser/tlast mismatch vs expected input beat");
            bad_frame = 1'b1;
          end
        end
        if (ok) begin
          qpop(k);
          in_flight--;
          cur_in = k;
          if (fair_chk) last_start[k] = frames_done;
          if (m_tlast) begin
            cur_in = -1;
            frames_done++;
            chk_fair();
          end
        end
      end else begin
        // S3: mid-frame, the next beat must be the next beat of the same frame
        if (qsize(cur_in) == 0) begin
          fail("S3", "output frame continues past the end of the expected input beats");
          bad_frame = 1'b1;
        end else begin
          b = qfront(cur_in);
          if (b.data === m_tdata && b.keep === m_tkeep &&
              b.user === m_tuser && b.last === m_tlast) begin
            qpop(cur_in);
            in_flight--;
          end else begin
            fail("S3", "mid-frame beat differs from the next expected beat of the selected input (interleaving or corruption)");
            bad_frame = 1'b1;
            qpop(cur_in);   // best effort: keep the model moving
            in_flight--;
          end
          if (m_tlast) begin
            cur_in = -1;
            frames_done++;
            chk_fair();
          end
        end
      end
    end
  end

  // ---- watchdog ----------------------------------------------------------------
  initial begin
    #20_000_000;
    $display("RESULT: FAIL (watchdog: no forward progress)");
    $finish;
  end

  // ---- main sequence --------------------------------------------------------------
  initial begin : main
    s_tdata  = '0;
    s_tkeep  = '0;
    s_tlast  = '0;
    s_tuser  = '0;
    s_tvalid = '0;
    m_tready = 1'b1;
    for (int j = 0; j < S_COUNT; j++) begin
      last_start[j] = 0;
      fcnt[j]       = 0;
      done_k[j]     = 1'b0;
    end

    bfm_reset(4);
    // S12: first cycle after release
    @(posedge clk);
    @(negedge clk);
    if (m_tvalid)
      fail("S12", "m_tvalid_o high on the first cycle after reset release");

    // ---- phase 1: single-beat frames, one input at a time (S2, S4, S5)
    for (int k = 0; k < S_COUNT; k++) begin
      for (int f = 0; f < 3; f++) send_frame(k, 1);
      bfm_idle(k);
    end
    drain_frames("phase1");

    // ---- phase 2: multi-beat frames with random backpressure (S8)
    fork
      begin
        for (int i = 0; i < 80; i++)
          bfm_ready(($urandom_range(0, 3) != 0));
        bfm_ready(1'b1);
      end
      begin
        for (int k = 0; k < S_COUNT; k++) begin
          for (int f = 0; f < 3; f++)
            send_frame(k, 1 + $urandom_range(0, 5));
          bfm_idle(k);
        end
      end
    join
    drain_frames("phase2");

    // ---- phase 2b: long stall in the middle of a frame (S8)
    fork
      begin
        bfm_ready(1'b0);
        repeat (12) @(posedge clk);
        bfm_ready(1'b1);
      end
      begin
        send_frame(1, 5);
        bfm_idle(1);
      end
    join
    drain_frames("phase2b");

    // ---- phase 3: continuous offered load on all inputs (S10)
    bfm_ready(1'b1);
    for (int j = 0; j < S_COUNT; j++) last_start[j] = frames_done;
    fair_chk = 1'b1;
    fork
      begin
        for (int f = 0; f < 16; f++) send_frame(0, 1 + $urandom_range(0, 2));
        bfm_idle(0);
        done_k[0] = 1'b1;
      end
      begin
        for (int f = 0; f < 16; f++) send_frame(1, 1 + $urandom_range(0, 2));
        bfm_idle(1);
        done_k[1] = 1'b1;
      end
      begin
        for (int f = 0; f < 16; f++) send_frame(2, 1 + $urandom_range(0, 2));
        bfm_idle(2);
        done_k[2] = 1'b1;
      end
      begin
        for (int f = 0; f < 16; f++) send_frame(3, 1 + $urandom_range(0, 2));
        bfm_idle(3);
        done_k[3] = 1'b1;
      end
    join
    fair_chk = 1'b0;
    drain_frames("phase3");

    // ---- phase 4: reset in the middle of a partially-emitted frame (S12)
    bfm_send(2, mk_data(2, fcnt[2], 0), 4'hF, 1'b0, 1'b0);
    bfm_send(2, mk_data(2, fcnt[2], 1), 4'hF, 1'b0, 1'b0);
    bfm_idle(2);                       // abandon frame at source (allowed, S5a)
    repeat (5) @(posedge clk);         // let the design start emitting it
    bfm_reset(2);
    s_tvalid = '0;                     // same negedge step as reset release
    for (int j = 0; j < S_COUNT; j++) qclr(j);
    in_flight = 0;
    cur_in    = -1;
    bad_frame = 1'b0;
    gen       = gen + 1;               // stale beats now fail the S12 check
    fcnt[2]++;

    // S12: first cycle after release
    @(posedge clk);
    @(negedge clk);
    if (m_tvalid)
      fail("S12", "m_tvalid_o high on the first cycle after reset release");

    // ---- phase 4b: post-reset traffic must still be forwarded correctly
    for (int k = 0; k < S_COUNT; k++) begin
      for (int f = 0; f < 2; f++) send_frame(k, 1 + $urandom_range(0, 3));
      bfm_idle(k);
    end
    drain_frames("phase4");

    // ---- final S5 sweep
    for (int j = 0; j < S_COUNT; j++) begin
      if (qsize(j) != 0)
        fail("S5", $sformatf("input %0d: %0d accepted beats never forwarded", j, qsize(j)));
    end

    if (errors == 0)
      $display("RESULT: PASS");
    else
      $display("RESULT: FAIL (%0d error(s))", errors);
    $finish;
  end

endmodule
```

### How the checks map to the spec

- **S3/S4** — every accepted input beat is pushed (at the negedge it is presented, so zero-latency pass-through designs are handled race-free) onto a per-input expected queue. The output checker identifies the source of a frame's first beat by the input number encoded in `tdata`, then requires an exact `tdata/tkeep/tuser/tlast` match against the *head* of that input's queue for every beat until `m_tlast_o`. Head-matching enforces per-input order; mid-frame matching against one queue enforces atomicity; the `last`-field comparison enforces the `m_tlast_o` rule.
- **S5** — `drain_frames` waits (bounded) for `in_flight` to reach zero; any residue is a loss/duplication failure.
- **S8** — phase 2 toggles `m_tready_i` randomly every cycle (including on `m_tlast_o` beats) and phase 2b holds it low for 12 cycles mid-frame.
- **S10** — phase 3 drives all four inputs with continuous valid and back-to-back frames while `m_tready_i` is high; on every completed output frame the checker verifies no still-offering input has gone more than 16 completed frames without beginning one.
- **S12** — reset is asserted mid-frame; a generation bit in the payload makes any pre-reset beat appearing afterwards an S12 failure, and `m_tvalid_o` is checked low on the first cycle after release.
- **S9/S11** and the out-of-scope list are never checked: no selection order, latency, ready promptness, or idle-cycle assumptions are made, and output fields are only examined when `m_tvalid_o` is high.
- The watchdog terminates the run unconditionally, catching a design that never selects an input.

reasoning:
Let me design the testbench.

Approach: reference model with per-input FIFO of expected beats. Since selection order is unconstrained, when a beat transfers on input k, we can't know yet which frame it belongs to... Actually we can: when a beat transfers on input k, we record it into a per-input "pending" queue. When the output emits a beat, we must attribute it to some input. Strategy: when output beat has m_tlast, we can... Hmm, better: attribute lazily. When an output beat transfers, we need to check it matches some input beat. Since frames are atomic (S3), we can track "current input" — once an output frame's first beat matches, we know which input. But first beat matching is ambiguous by value.

Better approach: make each beat's payload uniquely identifiable. Use unique data values encoding (input, frame#, beat#). Then when output beat arrives, decode which input/beat it claims, and check against bookkeeping: that this beat was indeed transferred on that input, hasn't been emitted before, and ordering per input. But faulty designs could corrupt data — then decode fails and we report S4 failure. That's fine.

But "correct but different" implementations forward data unmodified, so decode works.

Plan:
- Each input beat gets data = {k, frame_cnt[k], beat_cnt, some random-ish bits}. keep = random, user = random.
- On input transfer (posedge, s_tvalid[k]&&s_tready[k]): record beat in per-input queue `exp[k]` (data, keep, user, last), and mark global set of "in-flight" beats.
- On output transfer (m_tvalid && m_tready): pop expectation. Track current input `cur` (unknown until first beat of frame). If cur unknown: decode k from data (top bits), check exp[k] nonempty and head matches exactly (data, keep, user, last). If match, set cur=k, pop head, mark. If no match on any input's head... Actually with atomicity, a frame's beats come from one input contiguously. If cur known and frame not finished: head of exp[cur] must match. If mismatch → S3/S4 error. When m_tlast: cur = unknown.

Wait, but a subtlety: a source may abandon a partial frame (S5a) — but we always complete frames we start, so exp queues only contain beats of complete frames... no: we push beats as they transfer on input, before the frame completes. But since we always complete frames, all pushed beats eventually belong to complete frames. Fine.

But: could an implementation buffer beats from input A's frame 1, and while... no, S3 says once a beat of a frame appears on output, subsequent beats are same frame. But before any beat appears, the design may have accepted beats from multiple inputs. Fine — our head-matching handles it: we only match head of exp[k] for the decoded k.

Edge case: decode k from data — if data corrupted by faulty design, decoded k may be wrong or exp[k] empty → report S4. Good.

Also check S4 ordering: matching head of queue per input enforces order.

Check S5: at end of test, all exp queues empty and no in-flight. Also frames completed at input: every beat must appear. We complete all frames before ending, then drain output with m_tready high until... need to know when done: track total beats pushed vs popped; wait until counts equal, with timeout.

S10 fairness: run a phase where all inputs continuously offer frames (valid always high, back-to-back frames), m_tready high. Monitor output frames: record which input each completed output frame came from (cur during that frame). Check every window of 16 consecutive completed frames includes at least one frame from each input. Implementation: keep a counter per input of frames since last start; on each completed output frame, increment all counters, reset the counter for the frame's input; if any counter > 16 → fail S10. Actually "begin at least one frame within any window of 16 consecutive completed output frames" — if input k hasn't started a frame in the last 16 completed frames, fail. So after each completed frame, if since[k] >= 16 → fail. Let's use: on frame completion, for the input of that frame since[k]=0; others since++. Check since[k] <= 16 for all... Window of 16 consecutive completed frames: if input k starts none in frames i..i+15, fail. So if since[k] reaches 16 (16 frames completed without k starting), fail. Use threshold: fail if since[k] > 16? Let's be lenient: fail if since[k] >= 16 without a start... To be safe against correct-but-different, be lenient: fail when since[k] > 16 (i.e., 17 completed frames without k starting). Hmm, spec says "within any window of 16". If k starts a frame at frame index j (i.e., k's frame is the j-th completed), then windows fully after... Let's just check: after each completed frame, if since[k] >= 16 for some k, that means 16 frames completed since k last started (or beginning) — window of 16 with no k start → violation. But at the very beginning, before k ever starts, since[k] counts from start of continuous load. That's fine — the load is continuous from test start. But we should only enable this check during the continuous-load phase, and give some warmup. I'll enable check only during fairness phase, and start counting when the fairness phase begins (all inputs already offering). Use fail if since[k] >= 16... risk: borderline off-by-one rejecting correct design. Spec: "every input shall begin at least one frame within any window of 16 consecutive completed output frames." If frames complete at indices 1,2,3,...; input k begins frame that completes at index c. Window of 16 consecutive completed frames = {i..i+15}. If k's start (completion at c) is not in window, violation. So between consecutive completions of k's frames, gap must be ≤ 16? If k completes at c and next at c', then window {c+1..c+16} must contain c', so c' ≤ c+16, i.e., since[k] at most 16 when it completes. So fail if since[k] > 16 at any completion (i.e., 16 completions elapsed and k hasn't). I'll fail when since[k] > 16 after incrementing. That's exactly the boundary; safe.

But wait — "begin at least one frame" — begin, not complete. Frame begins when its first beat transfers on output. Hmm, "begin a frame" — I'll interpret as first output beat of a frame from k. Track when a frame from k starts (first beat), not completion. So: on output frame start of input k: since[k] counts completed frames since... Simpler: count completed output frames; on frame start from k, record. Check: for each completed-frame boundary, if 16 completed frames have passed since k last started → fail. Implement: counter `frames_done`; `last_start_frame[k]`. On frame start (first beat of new output frame) from k: last_start_frame[k] = frames_done. On frame completion: frames_done++. Check after each completion: if frames_done - last_start_frame[k] > 16 → fail. Initialize last_start_frame[k] = 0 at fairness phase start (frames_done=0). Actually during warmup frames may complete before all inputs offer; only check during fairness phase. I'll snapshot at fairness start: reset frames_done and last_start_frame to current... just set last_start_frame[k]=frames_done, then enable checking.

Hmm, but during fairness phase all inputs hold valid continuously with more frames — yes, our bfm will do that.

Also S12 reset test: send some beats, assert reset mid-stream, then after release check m_tvalid low on first cycle after release, and that no pre-reset beat appears. After reset, clear exp queues (design may drop). Actually S12 says beats before/during reset shall not appear after. So after reset, clear all expected queues, reset frame counters... but our unique data encoding uses frame counters — after reset, reuse counters but data values would repeat old ones. That's fine since we cleared queues. But "no beat that transferred before reset shall appear afterwards" — check: after reset, if output beat matches an old expected beat → fail S12. Simplest: clear queues, and check that first post-reset output beat's data isn't equal to any pre-reset... Instead: use a "generation" bit in data. Encode data with gen bit; after reset increment gen. Then if a stale beat appears, decode fails/mismatch → S4 error. To attribute to S12 specifically, could check gen bit. I'll just check gen mismatch → S12 fail.

Data encoding: DATA_WIDTH=32. Use bits: [31:28]=k(4 bits, S_COUNT=4 ok), [27]=gen, [26:16]=frame idx (11 bits), [15:0]=beat idx/pattern. Fine.

Test phases:
1. Basic: single-beat frames on each input, one at a time, others idle. m_tready high.
2. Multi-beat frames with backpressure (random m_tready toggling).
3. Concurrent inputs, multiple frames each, continuous load (fairness phase).
4. Reset mid-frame test.
5. Drain, final check S5.

Need concurrent output monitor since m_tready toggles. Structure:

- Input driver tasks run in sequence (not forked) mostly; for fairness phase need all 4 inputs offering simultaneously → fork/join. bfm_send blocks until transfer, so fork 4 drivers each sending N frames, plus a ready toggler... spec says m_tready high throughout for S10. Keep m_tready high during fairness phase.

